/* ===== ShiftWise Design System ===== */
:root {
  --color-primary: #0051C3;
  --color-primary-dark: #003D94;
  --color-primary-light: #E8F0FE;
  --color-accent: #DE5052;
  --color-accent-dark: #C23B3D;
  --color-accent-light: #FDEAEA;
  --color-navy: #0F172A;
  --color-navy-light: #1E293B;
  --color-gray-900: #111827;
  --color-gray-800: #1F2937;
  --color-gray-700: #374151;
  --color-gray-600: #4B5563;
  --color-gray-500: #6B7280;
  --color-gray-400: #9CA3AF;
  --color-gray-300: #D1D5DB;
  --color-gray-200: #E5E7EB;
  --color-gray-100: #F3F4F6;
  --color-gray-50: #F9FAFB;
  --color-white: #FFFFFF;
  --color-success: #059669;
  --color-warning: #D97706;

  --font-heading: 'Inter', system-ui, -apple-system, sans-serif;
  --font-body: 'Inter', system-ui, -apple-system, sans-serif;

  --fs-xs: 0.75rem;
  --fs-sm: 0.875rem;
  --fs-base: 1rem;
  --fs-lg: 1.125rem;
  --fs-xl: 1.25rem;
  --fs-2xl: 1.5rem;
  --fs-3xl: 1.875rem;
  --fs-4xl: 2.25rem;
  --fs-5xl: 3rem;
  --fs-6xl: 3.75rem;

  --fw-normal: 400;
  --fw-medium: 500;
  --fw-semibold: 600;
  --fw-bold: 700;
  --fw-extrabold: 800;

  --leading-tight: 1.15;
  --leading-snug: 1.3;
  --leading-normal: 1.6;

  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;

  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.5rem;
  --radius-full: 9999px;

  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -2px rgba(0,0,0,0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.1);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1);

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;

  --container-max: 1200px;
  --container-narrow: 800px;
}

/* ===== Reset ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font-body);
  font-size: var(--fs-base);
  font-weight: var(--fw-normal);
  line-height: var(--leading-normal);
  color: var(--color-gray-700);
  background: var(--color-white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
img, svg { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
button { font: inherit; cursor: pointer; border: none; background: none; }
ul, ol { list-style: none; }
input, textarea, select { font: inherit; }

/* ===== Utility ===== */
.container {
  width: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 var(--space-6);
}
.container--narrow { max-width: var(--container-narrow); }
.sr-only {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}

/* ===== Typography ===== */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: var(--fw-bold);
  line-height: var(--leading-tight);
  color: var(--color-navy);
}
h1 { font-size: var(--fs-5xl); font-weight: var(--fw-extrabold); }
h2 { font-size: var(--fs-4xl); }
h3 { font-size: var(--fs-2xl); }
h4 { font-size: var(--fs-xl); }
p + p { margin-top: var(--space-4); }
.text-center { text-align: center; }

/* ===== Buttons ===== */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: var(--space-2);
  padding: 0.8rem 1.75rem;
  font-size: var(--fs-base); font-weight: var(--fw-semibold);
  line-height: 1; border-radius: var(--radius-md);
  transition: all var(--transition-fast);
  white-space: nowrap;
}
.btn--primary {
  background: var(--color-accent);
  color: var(--color-white);
}
.btn--primary:hover { background: var(--color-accent-dark); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn--secondary {
  background: var(--color-white);
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
}
.btn--secondary:hover { background: var(--color-primary); color: var(--color-white); }
.btn--outline-white {
  background: transparent;
  color: var(--color-white);
  border: 2px solid rgba(255,255,255,0.5);
}
.btn--outline-white:hover { background: rgba(255,255,255,0.1); border-color: var(--color-white); }
.btn--large { padding: 1rem 2.25rem; font-size: var(--fs-lg); }
.btn--small { padding: 0.5rem 1.25rem; font-size: var(--fs-sm); }
.btn--full { width: 100%; }

/* ===== Header / Nav ===== */
.site-header {
  position: sticky; top: 0; z-index: 100;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-gray-200);
}
.site-header__inner {
  display: flex; align-items: center; justify-content: space-between;
  height: 72px;
}
.site-header__logo {
  display: flex; align-items: center; gap: var(--space-2);
  font-size: var(--fs-xl); font-weight: var(--fw-extrabold);
  color: var(--color-navy);
}
.site-header__logo svg { flex-shrink: 0; }
.site-header__nav { display: flex; align-items: center; gap: var(--space-8); }
.site-header__nav a {
  font-size: var(--fs-sm); font-weight: var(--fw-medium);
  color: var(--color-gray-600);
  transition: color var(--transition-fast);
  position: relative;
}
.site-header__nav a:hover,
.site-header__nav a.active { color: var(--color-primary); }
.site-header__nav a.active::after {
  content: ''; position: absolute; bottom: -4px; left: 0; right: 0;
  height: 2px; background: var(--color-primary); border-radius: 1px;
}
.site-header__cta { display: flex; align-items: center; gap: var(--space-3); }
.nav-toggle {
  display: none;
  width: 44px; height: 44px;
  align-items: center; justify-content: center;
  border-radius: var(--radius-md);
}
.nav-toggle span,
.nav-toggle span::before,
.nav-toggle span::after {
  display: block; width: 22px; height: 2px;
  background: var(--color-navy); border-radius: 2px;
  transition: all var(--transition-base);
}
.nav-toggle span { position: relative; }
.nav-toggle span::before,
.nav-toggle span::after { content: ''; position: absolute; left: 0; }
.nav-toggle span::before { top: -7px; }
.nav-toggle span::after { top: 7px; }
.nav-toggle.open span { background: transparent; }
.nav-toggle.open span::before { top: 0; transform: rotate(45deg); }
.nav-toggle.open span::after { top: 0; transform: rotate(-45deg); }

/* Mobile nav */
.mobile-nav {
  display: none;
  position: fixed; inset: 0; top: 72px; z-index: 99;
  background: var(--color-white);
  flex-direction: column;
  padding: var(--space-8) var(--space-6);
  transform: translateX(100%);
  transition: transform var(--transition-slow);
}
.mobile-nav.open { transform: translateX(0); }
.mobile-nav a {
  display: block; padding: var(--space-4) 0;
  font-size: var(--fs-lg); font-weight: var(--fw-medium);
  color: var(--color-navy);
  border-bottom: 1px solid var(--color-gray-200);
}
.mobile-nav a:hover { color: var(--color-primary); }
.mobile-nav .btn { margin-top: var(--space-6); }
.mobile-nav-overlay {
  display: none;
  position: fixed; inset: 0; top: 72px; z-index: 98;
  background: rgba(0,0,0,0.3);
  opacity: 0; transition: opacity var(--transition-slow);
}
.mobile-nav-overlay.open { opacity: 1; }

/* ===== Hero Sections ===== */
.hero {
  padding: var(--space-24) 0 var(--space-20);
  background: linear-gradient(135deg, var(--color-navy) 0%, #162544 50%, var(--color-primary-dark) 100%);
  color: var(--color-white);
  overflow: hidden;
  position: relative;
}
.hero::before {
  content: ''; position: absolute; inset: 0;
  background: radial-gradient(circle at 70% 30%, rgba(0,81,195,0.3) 0%, transparent 60%),
              radial-gradient(circle at 20% 80%, rgba(222,80,82,0.15) 0%, transparent 50%);
}
.hero__inner { position: relative; z-index: 1; }
.hero__content { max-width: 640px; }
.hero__badge {
  display: inline-flex; align-items: center; gap: var(--space-2);
  padding: var(--space-2) var(--space-4);
  background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: var(--radius-full);
  font-size: var(--fs-sm); font-weight: var(--fw-medium);
  margin-bottom: var(--space-6);
}
.hero h1 { color: var(--color-white); margin-bottom: var(--space-6); }
.hero p {
  font-size: var(--fs-lg); color: rgba(255,255,255,0.8);
  line-height: var(--leading-normal);
  margin-bottom: var(--space-8);
}
.hero__actions { display: flex; gap: var(--space-4); flex-wrap: wrap; }

.hero--light {
  background: linear-gradient(135deg, var(--color-gray-50) 0%, var(--color-primary-light) 100%);
  color: var(--color-gray-700);
  padding: var(--space-16) 0 var(--space-12);
}
.hero--light::before { display: none; }
.hero--light h1 { color: var(--color-navy); font-size: var(--fs-4xl); }
.hero--light p { color: var(--color-gray-600); font-size: var(--fs-lg); }

/* ===== Section Basics ===== */
.section { padding: var(--space-20) 0; }
.section--gray { background: var(--color-gray-50); }
.section--navy {
  background: linear-gradient(135deg, var(--color-navy) 0%, var(--color-navy-light) 100%);
  color: var(--color-white);
}
.section__header {
  text-align: center; max-width: 640px; margin: 0 auto var(--space-12);
}
.section__header h2 { margin-bottom: var(--space-4); }
.section__header p { font-size: var(--fs-lg); color: var(--color-gray-500); }
.section--navy .section__header p { color: rgba(255,255,255,0.7); }

.section__eyebrow {
  display: inline-block;
  font-size: var(--fs-sm); font-weight: var(--fw-semibold);
  text-transform: uppercase; letter-spacing: 0.08em;
  color: var(--color-primary);
  margin-bottom: var(--space-3);
}
.section--navy .section__eyebrow { color: var(--color-accent); }

/* ===== Features Grid ===== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--space-8);
}
.feature-card {
  padding: var(--space-8);
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-xl);
  transition: all var(--transition-base);
}
.feature-card:hover {
  border-color: var(--color-primary);
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}
.feature-card__icon {
  width: 52px; height: 52px;
  display: flex; align-items: center; justify-content: center;
  background: var(--color-primary-light);
  color: var(--color-primary);
  border-radius: var(--radius-lg);
  margin-bottom: var(--space-5);
}
.feature-card h3 { font-size: var(--fs-xl); margin-bottom: var(--space-3); }
.feature-card p { color: var(--color-gray-500); font-size: var(--fs-sm); line-height: var(--leading-normal); }

/* ===== How It Works ===== */
.steps-grid {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--space-8);
  counter-reset: step;
}
.step-card { text-align: center; position: relative; counter-increment: step; }
.step-card__number {
  width: 56px; height: 56px; margin: 0 auto var(--space-5);
  display: flex; align-items: center; justify-content: center;
  background: var(--color-primary);
  color: var(--color-white);
  font-size: var(--fs-xl); font-weight: var(--fw-bold);
  border-radius: var(--radius-full);
}
.step-card h3 { font-size: var(--fs-lg); margin-bottom: var(--space-3); }
.step-card p { font-size: var(--fs-sm); color: var(--color-gray-500); }

/* ===== Stats Banner ===== */
.stats-banner {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--space-8);
  padding: var(--space-12) 0;
}
.stat-item { text-align: center; }
.stat-item__value {
  font-size: var(--fs-5xl); font-weight: var(--fw-extrabold);
  color: var(--color-white);
  line-height: 1;
  margin-bottom: var(--space-2);
}
.stat-item__label {
  font-size: var(--fs-sm); color: rgba(255,255,255,0.7);
  font-weight: var(--fw-medium);
}
.stats-banner--blue .stat-item__value { color: var(--color-primary); }
.stats-banner--blue .stat-item__label { color: var(--color-gray-500); }

/* ===== Testimonials ===== */
.testimonials-carousel { position: relative; overflow: hidden; }
.testimonials-track {
  display: flex; transition: transform var(--transition-slow);
}
.testimonial-card {
  min-width: 100%;
  padding: var(--space-10);
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-xl);
  text-align: center;
}
.testimonial-card__stars {
  display: flex; justify-content: center; gap: var(--space-1);
  margin-bottom: var(--space-6);
  color: var(--color-warning);
}
.testimonial-card blockquote {
  font-size: var(--fs-xl); color: var(--color-navy);
  line-height: var(--leading-snug);
  font-weight: var(--fw-medium);
  margin-bottom: var(--space-6);
  max-width: 600px; margin-left: auto; margin-right: auto;
}
.testimonial-card__author {
  font-size: var(--fs-sm); font-weight: var(--fw-semibold);
  color: var(--color-navy);
}
.testimonial-card__role {
  font-size: var(--fs-sm); color: var(--color-gray-500);
}
.carousel-controls {
  display: flex; justify-content: center; align-items: center;
  gap: var(--space-6); margin-top: var(--space-8);
}
.carousel-btn {
  width: 48px; height: 48px;
  display: flex; align-items: center; justify-content: center;
  border: 2px solid var(--color-gray-300);
  border-radius: var(--radius-full);
  color: var(--color-gray-600);
  transition: all var(--transition-fast);
}
.carousel-btn:hover {
  border-color: var(--color-primary);
  color: var(--color-primary);
  background: var(--color-primary-light);
}
.carousel-dots { display: flex; gap: var(--space-2); }
.carousel-dot {
  width: 10px; height: 10px;
  border-radius: var(--radius-full);
  background: var(--color-gray-300);
  transition: all var(--transition-fast);
}
.carousel-dot.active {
  background: var(--color-primary);
  width: 28px;
}

/* ===== Pricing ===== */
.pricing-toggle {
  display: flex; align-items: center; justify-content: center;
  gap: var(--space-4); margin-bottom: var(--space-12);
}
.pricing-toggle__label {
  font-size: var(--fs-sm); font-weight: var(--fw-medium);
  color: var(--color-gray-500);
}
.pricing-toggle__label.active { color: var(--color-navy); font-weight: var(--fw-semibold); }
.pricing-toggle__switch {
  width: 52px; height: 28px;
  background: var(--color-gray-300);
  border-radius: var(--radius-full);
  position: relative;
  cursor: pointer;
  transition: background var(--transition-fast);
}
.pricing-toggle__switch.active { background: var(--color-primary); }
.pricing-toggle__switch::after {
  content: ''; position: absolute;
  top: 3px; left: 3px;
  width: 22px; height: 22px;
  background: var(--color-white);
  border-radius: var(--radius-full);
  transition: transform var(--transition-fast);
  box-shadow: var(--shadow-sm);
}
.pricing-toggle__switch.active::after { transform: translateX(24px); }
.pricing-toggle__badge {
  font-size: var(--fs-xs); font-weight: var(--fw-semibold);
  color: var(--color-success);
  background: #ECFDF5;
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
}

.pricing-grid {
  display: grid; grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8); align-items: start;
}
.pricing-card {
  background: var(--color-white);
  border: 2px solid var(--color-gray-200);
  border-radius: var(--radius-xl);
  padding: var(--space-10);
  position: relative;
  transition: all var(--transition-base);
}
.pricing-card:hover { box-shadow: var(--shadow-xl); }
.pricing-card--featured {
  border-color: var(--color-primary);
  box-shadow: var(--shadow-xl);
  transform: scale(1.03);
}
.pricing-card__popular {
  position: absolute; top: -14px; left: 50%; transform: translateX(-50%);
  background: var(--color-primary);
  color: var(--color-white);
  font-size: var(--fs-xs); font-weight: var(--fw-semibold);
  padding: var(--space-1) var(--space-4);
  border-radius: var(--radius-full);
  white-space: nowrap;
}
.pricing-card__name {
  font-size: var(--fs-lg); font-weight: var(--fw-semibold);
  color: var(--color-navy);
  margin-bottom: var(--space-2);
}
.pricing-card__desc {
  font-size: var(--fs-sm); color: var(--color-gray-500);
  margin-bottom: var(--space-6);
}
.pricing-card__price {
  display: flex; align-items: baseline; gap: var(--space-1);
  margin-bottom: var(--space-6);
}
.pricing-card__amount {
  font-size: var(--fs-5xl); font-weight: var(--fw-extrabold);
  color: var(--color-navy); line-height: 1;
}
.pricing-card__period {
  font-size: var(--fs-sm); color: var(--color-gray-500);
}
.pricing-card__features { margin-bottom: var(--space-8); }
.pricing-card__features li {
  display: flex; align-items: flex-start; gap: var(--space-3);
  padding: var(--space-3) 0;
  font-size: var(--fs-sm); color: var(--color-gray-600);
}
.pricing-card__features li svg { flex-shrink: 0; margin-top: 2px; }
.pricing-card__features li.disabled { color: var(--color-gray-400); }

/* ===== FAQ Accordion ===== */
.faq-list { max-width: 720px; margin: 0 auto; }
.faq-item {
  border-bottom: 1px solid var(--color-gray-200);
}
.faq-item:first-child { border-top: 1px solid var(--color-gray-200); }
.faq-question {
  width: 100%; display: flex; align-items: center; justify-content: space-between;
  padding: var(--space-5) 0;
  font-size: var(--fs-base); font-weight: var(--fw-semibold);
  color: var(--color-navy); text-align: left;
  cursor: pointer;
}
.faq-question svg {
  flex-shrink: 0; width: 20px; height: 20px;
  transition: transform var(--transition-base);
  color: var(--color-gray-400);
}
.faq-item.open .faq-question svg { transform: rotate(180deg); color: var(--color-primary); }
.faq-answer {
  max-height: 0; overflow: hidden;
  transition: max-height var(--transition-slow), padding var(--transition-slow);
}
.faq-item.open .faq-answer { max-height: 200px; }
.faq-answer p {
  padding-bottom: var(--space-5);
  font-size: var(--fs-sm); color: var(--color-gray-600);
  line-height: var(--leading-normal);
}

/* ===== CTA Section ===== */
.cta-section {
  padding: var(--space-20) 0;
  background: linear-gradient(135deg, var(--color-navy) 0%, var(--color-primary-dark) 100%);
  color: var(--color-white);
  text-align: center;
  position: relative; overflow: hidden;
}
.cta-section::before {
  content: ''; position: absolute;
  width: 600px; height: 600px;
  background: radial-gradient(circle, rgba(222,80,82,0.15), transparent 70%);
  top: -200px; right: -100px;
}
.cta-section::after {
  content: ''; position: absolute;
  width: 400px; height: 400px;
  background: radial-gradient(circle, rgba(0,81,195,0.2), transparent 70%);
  bottom: -150px; left: -50px;
}
.cta-section__inner { position: relative; z-index: 1; max-width: 640px; margin: 0 auto; }
.cta-section h2 { color: var(--color-white); margin-bottom: var(--space-4); }
.cta-section p {
  font-size: var(--fs-lg); color: rgba(255,255,255,0.8);
  margin-bottom: var(--space-8);
}

/* ===== Footer ===== */
.site-footer {
  background: var(--color-navy);
  color: rgba(255,255,255,0.7);
  padding: var(--space-16) 0 var(--space-8);
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: var(--space-10);
  margin-bottom: var(--space-12);
}
.footer-brand p {
  font-size: var(--fs-sm); margin-top: var(--space-4);
  line-height: var(--leading-normal);
  max-width: 280px;
}
.footer-col h4 {
  font-size: var(--fs-sm); font-weight: var(--fw-semibold);
  color: var(--color-white);
  text-transform: uppercase; letter-spacing: 0.05em;
  margin-bottom: var(--space-4);
}
.footer-col a {
  display: block;
  font-size: var(--fs-sm);
  padding: var(--space-2) 0;
  transition: color var(--transition-fast);
}
.footer-col a:hover { color: var(--color-white); }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: var(--space-8);
  display: flex; align-items: center; justify-content: space-between;
  font-size: var(--fs-xs);
}
.footer-social { display: flex; gap: var(--space-4); }
.footer-social a {
  width: 36px; height: 36px;
  display: flex; align-items: center; justify-content: center;
  border-radius: var(--radius-full);
  background: rgba(255,255,255,0.08);
  transition: background var(--transition-fast);
}
.footer-social a:hover { background: rgba(255,255,255,0.2); }

/* ===== Contact Form ===== */
.contact-grid {
  display: grid; grid-template-columns: 1.2fr 0.8fr; gap: var(--space-12);
  align-items: start;
}
.form-group { margin-bottom: var(--space-5); }
.form-group label {
  display: block; font-size: var(--fs-sm); font-weight: var(--fw-medium);
  color: var(--color-navy); margin-bottom: var(--space-2);
}
.form-group label .required { color: var(--color-accent); }
.form-input {
  width: 100%; padding: 0.75rem 1rem;
  border: 2px solid var(--color-gray-200);
  border-radius: var(--radius-md);
  font-size: var(--fs-base);
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
  background: var(--color-white);
}
.form-input:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(0,81,195,0.1);
}
.form-input.error { border-color: var(--color-accent); }
.form-error {
  display: none; font-size: var(--fs-xs); color: var(--color-accent);
  margin-top: var(--space-1);
}
.form-input.error + .form-error { display: block; }
textarea.form-input { resize: vertical; min-height: 120px; }
.form-row { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-5); }

.form-success {
  display: none; text-align: center; padding: var(--space-10);
}
.form-success.show { display: block; }
.form-success__icon {
  width: 64px; height: 64px; margin: 0 auto var(--space-5);
  background: #ECFDF5; border-radius: var(--radius-full);
  display: flex; align-items: center; justify-content: center;
  color: var(--color-success);
}
.form-success h3 { margin-bottom: var(--space-3); }
.form-success p { color: var(--color-gray-500); }

.contact-info-card {
  background: var(--color-gray-50);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
}
.contact-info-item {
  display: flex; gap: var(--space-4);
  padding: var(--space-5) 0;
  border-bottom: 1px solid var(--color-gray-200);
}
.contact-info-item:last-child { border-bottom: none; }
.contact-info-item__icon {
  width: 44px; height: 44px; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  background: var(--color-primary-light);
  color: var(--color-primary);
  border-radius: var(--radius-lg);
}
.contact-info-item h4 {
  font-size: var(--fs-sm); margin-bottom: var(--space-1);
}
.contact-info-item p { font-size: var(--fs-sm); color: var(--color-gray-500); }

/* ===== About / Team ===== */
.team-grid {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--space-8);
}
.team-card { text-align: center; }
.team-card__avatar {
  width: 120px; height: 120px; margin: 0 auto var(--space-5);
  background: linear-gradient(135deg, var(--color-primary-light), var(--color-gray-100));
  border-radius: var(--radius-full);
  display: flex; align-items: center; justify-content: center;
  font-size: var(--fs-3xl); font-weight: var(--fw-bold);
  color: var(--color-primary);
}
.team-card h3 { font-size: var(--fs-lg); margin-bottom: var(--space-1); }
.team-card p { font-size: var(--fs-sm); color: var(--color-gray-500); }

.mission-content {
  display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-12);
  align-items: center;
}
.mission-content p { margin-bottom: var(--space-4); font-size: var(--fs-lg); line-height: var(--leading-normal); }
.mission-visual {
  background: linear-gradient(135deg, var(--color-primary-light), var(--color-gray-100));
  border-radius: var(--radius-2xl);
  aspect-ratio: 4/3;
  display: flex; align-items: center; justify-content: center;
}
.mission-visual svg { width: 160px; height: 160px; color: var(--color-primary); opacity: 0.5; }

/* ===== Feature Detail Sections ===== */
.feature-detail {
  display: grid; grid-template-columns: 1fr 1fr;
  gap: var(--space-12); align-items: center;
}
.feature-detail--reversed { direction: rtl; }
.feature-detail--reversed > * { direction: ltr; }
.feature-detail__content h3 { font-size: var(--fs-3xl); margin-bottom: var(--space-4); }
.feature-detail__content p { color: var(--color-gray-600); margin-bottom: var(--space-6); line-height: var(--leading-normal); }
.feature-detail__visual {
  background: linear-gradient(135deg, var(--color-primary-light), var(--color-gray-100));
  border-radius: var(--radius-2xl);
  aspect-ratio: 4/3;
  display: flex; align-items: center; justify-content: center;
}
.feature-detail__visual svg { width: 120px; height: 120px; color: var(--color-primary); opacity: 0.4; }
.feature-detail__list { list-style: none; }
.feature-detail__list li {
  display: flex; align-items: center; gap: var(--space-3);
  padding: var(--space-2) 0;
  font-size: var(--fs-sm); color: var(--color-gray-600);
}
.feature-detail__list li svg { color: var(--color-success); flex-shrink: 0; }

/* ===== Integrations ===== */
.integrations-grid {
  display: grid; grid-template-columns: repeat(2, 1fr); gap: var(--space-8);
}
.integration-card {
  padding: var(--space-8);
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-xl);
}
.integration-card h3 {
  font-size: var(--fs-xl); margin-bottom: var(--space-3);
  display: flex; align-items: center; gap: var(--space-3);
}
.integration-card h3 svg { color: var(--color-primary); }
.integration-card__logos {
  display: flex; flex-wrap: wrap; gap: var(--space-3);
  margin-top: var(--space-4);
}
.integration-logo {
  padding: var(--space-2) var(--space-4);
  background: var(--color-gray-50);
  border-radius: var(--radius-md);
  font-size: var(--fs-sm); font-weight: var(--fw-medium);
  color: var(--color-gray-700);
}

/* ===== Pricing Teaser (Home) ===== */
.pricing-teaser-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-6);
}
.pricing-teaser-card {
  text-align: center;
  padding: var(--space-8);
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-xl);
  transition: all var(--transition-base);
}
.pricing-teaser-card:hover { box-shadow: var(--shadow-lg); }
.pricing-teaser-card__name {
  font-size: var(--fs-lg); font-weight: var(--fw-semibold);
  color: var(--color-navy); margin-bottom: var(--space-2);
}
.pricing-teaser-card__price {
  font-size: var(--fs-3xl); font-weight: var(--fw-extrabold);
  color: var(--color-primary); margin-bottom: var(--space-1);
}
.pricing-teaser-card__period {
  font-size: var(--fs-sm); color: var(--color-gray-500);
  margin-bottom: var(--space-5);
}
.pricing-teaser-card__features {
  font-size: var(--fs-sm); color: var(--color-gray-600);
  margin-bottom: var(--space-6);
}
.pricing-teaser-card__features li { padding: var(--space-2) 0; }

/* ===== Animations ===== */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}
.animate-in {
  opacity: 0; transform: translateY(24px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}
.animate-in.visible {
  opacity: 1; transform: translateY(0);
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  h1 { font-size: var(--fs-4xl); }
  h2 { font-size: var(--fs-3xl); }
  .steps-grid { grid-template-columns: repeat(2, 1fr); }
  .stats-banner { grid-template-columns: repeat(2, 1fr); gap: var(--space-6); }
  .pricing-grid { grid-template-columns: 1fr; max-width: 480px; margin: 0 auto; }
  .pricing-card--featured { transform: none; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .team-grid { grid-template-columns: repeat(2, 1fr); }
  .feature-detail { grid-template-columns: 1fr; gap: var(--space-8); }
  .feature-detail--reversed { direction: ltr; }
  .feature-detail__visual { order: -1; }
  .mission-content { grid-template-columns: 1fr; }
  .integrations-grid { grid-template-columns: 1fr; }
  .contact-grid { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  :root { --space-20: 3.5rem; --space-24: 4rem; }
  h1 { font-size: var(--fs-3xl); }
  h2 { font-size: var(--fs-2xl); }
  .container { padding: 0 var(--space-4); }

  .site-header__nav,
  .site-header__cta { display: none; }
  .nav-toggle { display: flex; }
  .mobile-nav { display: flex; }
  .mobile-nav-overlay { display: block; }

  .hero { padding: var(--space-16) 0 var(--space-12); }
  .hero__actions { flex-direction: column; }
  .hero__actions .btn { width: 100%; }

  .steps-grid { grid-template-columns: 1fr; }
  .stats-banner { grid-template-columns: repeat(2, 1fr); }
  .stat-item__value { font-size: var(--fs-4xl); }

  .features-grid { grid-template-columns: 1fr; }

  .pricing-teaser-grid { grid-template-columns: 1fr; }

  .footer-grid { grid-template-columns: 1fr; gap: var(--space-8); }
  .footer-bottom { flex-direction: column; gap: var(--space-4); text-align: center; }

  .form-row { grid-template-columns: 1fr; }
  .team-grid { grid-template-columns: 1fr; gap: var(--space-6); }
}

